$:set -euo pipefail
printf 'REVISION='; git rev-parse HEAD
if test -f README.md; then printf 'README=present\n'; else printf 'README=absent\n'; fi
if test -f AGENTS.md; then printf 'AGENTS=present\n'; else printf 'AGENTS=absent\n'; exit 1; fi
node <<'NODE'
const fs=require('node:fs'),crypto=require('node:crypto');
const d=fs.readFileSync('AGENTS.md','utf8');
const m=d.match(/## I\. Imperatives — SHALL\n\n~~~json\n([\s\S]*?)\n~~~/);
if(!m)throw Error('Imperative section not found');
const x=JSON.parse(m[1]);
console.log(JSON.stringify({sha256:crypto.createHash('sha256').update(d).digest('hex'),bytes:Buffer.byteLength(d),rules:x.rules.length,imperative_heading_index:d.indexOf('## I. Imperatives'),procedures_heading_index:d.indexOf('## II. Procedures'),procedure_headings:[...d.matchAll(/^### \d+\. .+$/gm)].map(v=>v[0]),scratchpad_matches:d.split('scratchpad').length-1,first_rule:x.rules[0],last_rule:x.rules.at(-1)}));
console.log('START:'+d.slice(0,700));
console.log('END:'+d.slice(-1000));
NODE
